e:linea:l2beat"]},"watch":[{"signal":"TVL, repeat volume, fees, burns and incentive-adjusted users.","implication":"Persistence would show demand beyond a short rebound.","source_refs":["source:linea:tvl","source:linea:volume","source:linea:fees","source:linea:token"]},{"signal":"Yield losses, reserve buffers, sequencer incidents and upgrade controls.","implication":"Reliable operation and broader control would reduce current risk.","source_refs":["source:linea:yield","source:linea:l2beat"]}],"unknowns":[{"question":"How much volume remains after incentives normalize?","resolution_trigger":"A two-quarter incentive-adjusted cohort study."},{"question":"What losses can Yield Boost absorb?","resolution_trigger":"A published stress test and reconciled reserve statement."},{"question":"Who controls sequencer and upgrades by beneficial owner?","resolution_trigger":"An independent entity-level control map."},{"question":"When do roadmap proving changes become production defaults?","resolution_trigger":"Versioned mainnet activation and independent verification."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Linea

