INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Linea',
  'Linea offered strong Ethereum compatibility and Consensys distribution, but those advantages did not keep peak capital on the chain. The token launch and Yield Boost added incentives after the large liquidity cycle had already turned. A one-month volume rebound is encouraging, yet it is too short to outweigh the TVL collapse or prove repeat demand. Centralized sequencing and no-delay upgrades also limit the trust advantage the rollup is trying to sell.',
  'bearish',
  'Linea is operating but declining. It has shipped a token, burns and Yield Boost, and recent DEX volume improved sharply. However, TVL is 98.40% below peak and LINEA is roughly 95% below its high. The next phase is not another announcement; it is whether capital, users and fees persist after the incentive ramp while operational control becomes less concentrated.',
  '2026-08-03',
  '[{"id":"source:linea:overview","title":"Linea network overview","url":"https://linea.build/","publisher":"Linea","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current network positioning, ETH gas and LINEA economics."},{"id":"source:linea:roadmap","title":"Linea product roadmap update","url":"https://community.linea.build/t/linea-product-roadmap-update/10607","publisher":"Linea","published_at":"2025-08-08","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Dated roadmap targets and dual-burn design."},{"id":"source:linea:token","title":"2025 launched a new era for Linea and L2s","url":"https://linea.build/blog/2025-launched-a-new-era-for-linea-and-l2s","publisher":"Linea","published_at":"2025-12-11","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Dated token launch, allocation and burn totals."},{"id":"source:linea:yield","title":"Yield Boost is activated","url":"https://linea.build/blog/yield-boost-is-activated","publisher":"Linea","published_at":"2026-03-30","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Activation and phased reserve-deployment limits."},{"id":"source:linea:proving","title":"Linea proved the EVM the hard way","url":"https://linea.build/blog/linea-proved-the-evm-the-hard-way-heres-what-comes-next","publisher":"Linea","published_at":"2026-03-29","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current proving architecture and forward work."},{"id":"source:linea:l2beat","title":"Linea risk analysis","url":"https://l2beat.com/scaling/projects/linea","publisher":"L2BEAT","source_role":"independent","tier":"A","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current stage, operator, upgrade, exit and incident panels."},{"id":"source:linea:tvl","title":"Linea historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Linea","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:linea:volume","title":"Linea DEX volume API","url":"https://api.llama.fi/overview/dexs/Linea?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:linea:fees","title":"Linea fees API","url":"https://api.llama.fi/overview/fees/Linea?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:linea:revenue","title":"Linea revenue API","url":"https://api.llama.fi/overview/fees/Linea?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:linea:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Linea row and peggedUSD field."},{"id":"source:linea:market","title":"Linea token market data","url":"https://api.coingecko.com/api/v3/coins/linea","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:linea","type":"blockchain","slug":"linea","name":"Linea","aliases":[]},"classification":{"subtype":"Ethereum ZK rollup","tags":["zk_rollup","ethereum","eth_gas","linea_token"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:linea:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:linea:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Linea is an Ethereum rollup built to behave like the EVM while proving batches with zero-knowledge proofs. Users pay gas in ETH. LINEA is a separate ecosystem token, not the gas asset. The chain now combines Ethereum settlement with a dual-burn design and a phased program that puts some bridged ETH to work. That program is live, but future proving, decentralization and performance targets remain roadmap items.","as_of":"2026-08-03","claim_ids":["claim:linea:section:what_it_is:1","claim:linea:section:what_it_is:2"]},"what_happened":{"body":"Linea launched as Consensys’ EVM-equivalent rollup, introduced LINEA in 2025 and activated Yield Boost in March 2026. TVL reached $1.68 billion in September 2025 before falling to $26.87 million, a 98.40% drawdown. Dollar stablecoins were $37.46 million. Thirty-day DEX volume was $31.99 million and had jumped 526.98% from the prior provider comparison, while fees were $226,927.64 and retained revenue was $204,181.15.","as_of":"2026-08-03","claim_ids":["claim:linea:section:what_happened:1","claim:linea:section:what_happened:2"]},"why_this_outcome":{"body":"Linea offered strong Ethereum compatibility and Consensys distribution, but those advantages did not keep peak capital on the chain. The token launch and Yield Boost added incentives after the large liquidity cycle had already turned. A one-month volume rebound is encouraging, yet it is too short to outweigh the TVL collapse or prove repeat demand. Centralized sequencing and no-delay upgrades also limit the trust advantage the rollup is trying to sell.","as_of":"2026-08-03","claim_ids":["claim:linea:section:why_this_outcome:1","claim:linea:section:why_this_outcome:2"]},"strategic_choices":{"body":"Linea chose close EVM compatibility, ETH gas and Ethereum settlement rather than a sovereign chain. It later launched LINEA with an ecosystem-heavy allocation and added a dual burn that links activity to ETH and LINEA. Yield Boost deploys only a staged share of bridged assets, beginning with a buffer rather than putting every deposit at risk. These choices improve familiarity and potential value capture, but they add token, reserve-management and governance complexity.","as_of":"2026-08-03","claim_ids":["claim:linea:section:strategic_choices:1","claim:linea:section:strategic_choices:2"]},"operating_model":{"body":"Linea batches transactions through a centralized sequencer and posts data to Ethereum. Proofs support settlement, but current users still depend on operator and upgrade controls. L2BEAT classified Linea Stage 0 at the review date, with no force-inclusion path and no user exit window before upgrades. Yield Boost adds external strategy and reserve dependencies to the bridge system. Those controls are different from the security of Ethereum itself.","as_of":"2026-08-03","claim_ids":["claim:linea:section:operating_model:1","claim:linea:section:operating_model:2"]},"token_and_value_capture":{"body":"ETH remains the gas asset. LINEA adds governance and ecosystem incentives, while the dual-burn design destroys some ETH and LINEA as network activity generates fees. CoinGecko observed LINEA at $0.00223742, with a $54.10 million market capitalization and $160.19 million fully diluted value, about 95.21% below its recorded high. The burn is real but still small relative to token supply and cannot substitute for durable users and fees.","as_of":"2026-08-03","claim_ids":["claim:linea:section:token_and_value_capture:1","claim:linea:section:token_and_value_capture:2"]},"counterfactual":{"body":"Linea could have stayed an ETH-only rollup without a new token, avoiding dilution and governance overhead but giving up an incentive and coordination tool. It could also have delayed bridge-yield deployment until control was broader, sacrificing near-term rewards for a simpler risk model. A stronger test than either story is whether liquidity and paying use stay after incentives normalize.","as_of":"2026-08-03","claim_ids":["claim:linea:section:counterfactual:1","claim:linea:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are thin retained liquidity, centralized control, token dilution, bridge strategy losses and roadmap slippage. The 2025 token launch does not establish who will hold or use LINEA through a full market cycle. The reviewed sources also do not provide repeat-user cohorts, incentive-adjusted volume, a complete reserve stress test or a fully independent map of sequencer and upgrade authority.","as_of":"2026-08-03","claim_ids":["claim:linea:section:risks_and_unknowns:1","claim:linea:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Linea is operating but declining. It has shipped a token, burns and Yield Boost, and recent DEX volume improved sharply. However, TVL is 98.40% below peak and LINEA is roughly 95% below its high. The next phase is not another announcement; it is whether capital, users and fees persist after the incentive ramp while operational control becomes less concentrated.","as_of":"2026-08-03","claim_ids":["claim:linea:section:lifecycle:1","claim:linea:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a smaller active rollup with occasional incentive-led bursts. The call improves if TVL holds, the volume rebound persists, fees grow without outsized rewards and L2BEAT records meaningful control improvements. Watch Yield Boost losses and buffers, burn transactions, token unlocks, sequencer incidents, upgrade delays and repeat-user activity. The call worsens if liquidity resumes falling or roadmap claims continue to outrun production controls.","as_of":"2026-08-03","claim_ids":["claim:linea:section:outlook_and_watch:1","claim:linea:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:linea:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":26874022,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:linea:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:linea:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":37455540.76503395,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:linea:metric:stablecoins-latest"],"quality_flags":[]},{"id":"metric:linea:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":31985674.01,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:linea:metric:dex-volume-30d"],"quality_flags":["not_unique_users"]},{"id":"metric:linea:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":226927.64,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_id