-- canonical-profile-start Dexalot
INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Dexalot',
  'The dedicated chain gives the order book predictable execution and lets Dexalot shape fees, APIs and cross-chain settlement around trading. That product focus helped preserve meaningful flow despite a small capital footprint. The trade-off is concentration: one exchange is effectively the chain’s reason to exist, and its initial validator plan placed eight of ten nodes with the foundation. Rising volume can therefore coexist with weak diversification, limited revenue and a token that is far below its high.',
  'mixed',
  'Dexalot is operating and middling. It has a real order-book product and strong recent volume, but only modest fees, low reported TVL and concentrated product risk. The exchange should not be scored twice as both a successful chain and a separate venue. The next lifecycle test is whether rising flow produces retained users, revenue and broader security without depending on one operator or temporary market-making activity.',
  '2026-08-03',
  '[{"id":"source:dexalot:node","title":"Dexalot L1 node guide","url":"https://docs.dexalot.com/en/tutorials/runanode/","publisher":"Dexalot","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current sovereign Avalanche L1 and exchange description."},{"id":"source:dexalot:portfolio","title":"Dexalot Portfolio contract","url":"https://docs.dexalot.com/en/contracts/Portfolio.html","publisher":"Dexalot","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Origin-chain asset custody and balance representation."},{"id":"source:dexalot:validation","title":"Dexalot Validation Program","url":"https://docs.dexalot.com/en/articles/validation/","publisher":"Dexalot","published_at":"2022-10-24","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Initial ten-node validator plan and foundation operation of eight nodes."},{"id":"source:dexalot:litepaper","title":"Dexalot litepaper","url":"https://docs.dexalot.com/en/articles/litepaper/","publisher":"Dexalot","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"ALOT gas, staking, governance and incentive design."},{"id":"source:dexalot:avalanche","title":"Avalanche Evergreen and application-specific networks","url":"https://kr.avax.network/blog/avalanche-launches-evergreen-subnets-for-institutional-blockchain-deployments","publisher":"Avalanche","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Third-party description of Dexalot as an on-chain order-book network."},{"id":"source:dexalot:tvl","title":"Dexalot historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Dexalot","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:dexalot:volume","title":"Dexalot DEX volume API","url":"https://api.llama.fi/overview/dexs/Dexalot?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:dexalot:fees","title":"Dexalot fees API","url":"https://api.llama.fi/overview/fees/Dexalot?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:dexalot:revenue","title":"Dexalot revenue API","url":"https://api.llama.fi/overview/fees/Dexalot?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:dexalot:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Dexalot row and peggedUSD field."},{"id":"source:dexalot:market","title":"Dexalot token market data","url":"https://api.coingecko.com/api/v3/coins/dexalot","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:dexalot","type":"blockchain","slug":"dexalot","name":"Dexalot","aliases":[]},"classification":{"subtype":"exchange-specific Avalanche L1","tags":["avalanche_l1","order_book","appchain","omnichain"],"chains":["Avalanche"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:dexalot:status"]},"outcome":{"label":"middling","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"medium","claim_ids":["claim:dexalot:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Dexalot is both an exchange and the Avalanche L1 built to run that exchange. Its central limit order book supports limit and market orders, swaps from connected chains and programmatic trading. Assets can remain locked on their origin chains while balances are represented on Dexalot L1, so the chain’s TVL is not a complete measure of order-book liquidity. Its chain activity and exchange activity are the same business flow and must not be added together.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:what_it_is:1","claim:dexalot:section:what_it_is:2"]},"what_happened":{"body":"Dexalot moved from an Avalanche C-Chain application to a dedicated exchange chain. By 2026-08-03, reported TVL was $1.41 million, down 85.65% from its January 2025 peak. The same chain recorded $393.17 million in 30-day DEX volume, up 166.48% from the provider’s prior-month comparison. Fees were $21,501 and retained revenue was $8,525. Those numbers show a working exchange, but not a broad, independent chain economy.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:what_happened:1","claim:dexalot:section:what_happened:2"]},"why_this_outcome":{"body":"The dedicated chain gives the order book predictable execution and lets Dexalot shape fees, APIs and cross-chain settlement around trading. That product focus helped preserve meaningful flow despite a small capital footprint. The trade-off is concentration: one exchange is effectively the chain’s reason to exist, and its initial validator plan placed eight of ten nodes with the foundation. Rising volume can therefore coexist with weak diversification, limited revenue and a token that is far below its high.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:why_this_outcome:1","claim:dexalot:section:why_this_outcome:2"]},"strategic_choices":{"body":"Dexalot chose a sovereign order-book chain instead of remaining only a smart contract on Avalanche C-Chain. It keeps many assets on origin chains and communicates balances into the trading system, reducing the need to bridge every asset into one pool. It also made ALOT the gas, staking and governance asset. These choices create a faster, specialized product, but they concentrate security, token demand and chain survival around the exchange operator and its cross-chain messaging.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:strategic_choices:1","claim:dexalot:section:strategic_choices:2"]},"operating_model":{"body":"Dexalot uses an Avalanche-compatible validator set and EVM contracts to run an on-chain order book. The launch plan described ten nodes, eight operated by the foundation and two by vetted outside users. That is a dated starting configuration, not proof of current ownership. The Portfolio layer and messaging systems coordinate deposits and withdrawals across chains, while users depend on exchange contracts, admin roles, validator liveness and message delivery.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:operating_model:1","claim:dexalot:section:operating_model:2"]},"token_and_value_capture":{"body":"ALOT pays gas and is described as a staking, governance and incentive token. CoinGecko observed a $0.00979093 price, $625,917 market capitalization and $979,093 fully diluted value, about 99.65% below its recorded high. The chain produced fees and some retained revenue, but the reviewed sources do not establish that holders receive a continuing contractual share of exchange profit. Early fee-sharing language was time-bounded and should not be projected forward.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:token_and_value_capture:1","claim:dexalot:section:token_and_value_capture:2"]},"counterfactual":{"body":"Dexalot could have stayed on Avalanche C-Chain, reusing a broader validator set and ecosystem while accepting shared blockspace and less control. It could also have used a conventional AMM, simplifying liquidity accounting but giving up a professional order-book experience. The practical test is whether the dedicated chain produces better spreads, retention and fee economics after validator and messaging costs, not whether it can report a large gross volume number.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:counterfactual:1","claim:dexalot:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are single-product dependence, validator concentration, cross-chain message failures, contract admin power and thin retained economics. TVL understates origin-chain assets, but high gross volume can also overstate durable users because the provider does not identify market makers or repeat cohorts. We lack a current validator map, audited cross-chain exposure, full operator costs and a clear statement of current ALOT fee rights.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:risks_and_unknowns:1","claim:dexalot:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Dexalot is operating and middling. It has a real order-book product and strong recent volume, but only modest fees, low reported TVL and concentrated product risk. The exchange should not be scored twice as both a successful chain and a separate venue. The next lifecycle test is whether rising flow produces retained users, revenue and broader security without depending on one operator or temporary market-making activity.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:lifecycle:1","claim:dexalot:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a useful niche exchange chain rather than a broad L1 ecosystem. The call improves if volume remains high, spreads stay competitive, revenue grows, validators broaden and cross-chain withdrawals stay reliable. Watch market-maker concentration, repeat traders, validator entities, message failures, contract upgrades, fee distribution and ALOT supply. The call worsens if flow disappears when incentives or market makers leave, or if a bridge or validator incident interrupts withdrawals.","as_of":"2026-08-03","claim_ids":["claim:dexalot:section:outlook_and_watch:1","claim:dexalot:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:dexalot:tvl-latest:2026-08-03","dimension":"tvl","label":"Reported chain TVL","value":1409039,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:dexalot:metric:tvl-latest"],"quality_flags":["origin_chain_assets_excluded"]},{"id":"metric:dexalot:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"Exchange volume (30d)","value":393174818,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d; same flow as the Dexalot exchange.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:dexalot:metric:dex-volume-30d"],"quality_flags":["do_not_add_to_exchange_volume","not_unique_users"]},{"id":"metric:dexalot:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":21501,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03"