INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Cronos',
  'Crypto.com distribution was Cronos’ largest advantage, but a general-purpose EVM chain did not keep most of the 2022 capital cycle. Users could access similar DeFi products on larger networks, and current DEX volume is shrinking. The 70 billion CRO reserve reversal also weakened the scarcity story after the earlier burn and increased governance concentration. Cronos Labs now argues that first-party apps distributed through Crypto.com are a better strategy; that is a plausible response, not evidence of a completed turnaround.',
  'bearish',
  'Cronos is operating but declining. It still holds meaningful capital and stablecoins, and Crypto.com remains a strong distribution channel. However, TVL is 92.13% below peak, monthly DEX flow is contracting and retained revenue is small compared with the token’s fully diluted value. The first-party app strategy may create a second act, but the lifecycle call changes only after those products produce durable users, fees and transparent value capture.',
  '2026-08-03',
  '[{"id":"source:cronos:reserve","title":"The new golden age for Cronos","url":"https://blog.cronos.com/p/the-new-golden-age-for-cronos","publisher":"Cronos Labs","published_at":"2025-03-03","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Strategic-reserve proposal and proposed vesting."},{"id":"source:cronos:economics","title":"A new era for CRO","url":"https://blog.cronos.com/p/a-new-era-for-cro","publisher":"Cronos Labs","published_at":"2026-05-05","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Dated staking and emission proposal; proposal language retained."},{"id":"source:cronos:strategy","title":"Cronos Labs names Ryan Wyatt as CEO","url":"https://blog.cronos.com/p/cronos-labs-names-ryan-wyatt-as-ceo","publisher":"Cronos Labs","published_at":"2025-12-15","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Distribution-led financial-app strategy and current plans."},{"id":"source:cronos:validators","title":"Cronos EVM chain FAQ","url":"https://github.com/crypto-org-chain/chain-main/discussions/442","publisher":"Cronos","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"PoA validator admission and partner-validator description."},{"id":"source:cronos:statement","title":"Crypto.com crypto asset statement","url":"https://crypto.com/document/crypto_asset_statement","publisher":"Crypto.com","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current CRO utility, supply and multi-network boundary."},{"id":"source:cronos:tvl","title":"Cronos historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Cronos","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:cronos:volume","title":"Cronos DEX volume API","url":"https://api.llama.fi/overview/dexs/Cronos?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:cronos:fees","title":"Cronos fees API","url":"https://api.llama.fi/overview/fees/Cronos?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:cronos:revenue","title":"Cronos revenue API","url":"https://api.llama.fi/overview/fees/Cronos?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:cronos:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Cronos row and peggedUSD field."},{"id":"source:cronos:market","title":"Cronos token market data","url":"https://api.coingecko.com/api/v3/coins/crypto-com-chain","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:cronos","type":"blockchain","slug":"cronos","name":"Cronos","aliases":[]},"classification":{"subtype":"Crypto.com-distributed EVM layer 1","tags":["evm","cosmos_sdk","crypto_com","proof_of_authority"],"chains":[],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:cronos:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:cronos:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Cronos is the EVM-compatible chain distributed through Crypto.com’s exchange, wallet and consumer products. It is built with Cosmos SDK and Ethermint technology, uses CRO for gas and relies on an admitted validator group. This report covers the Cronos EVM chain, not Cronos POS or Cronos zkEVM. The operator’s newer plan is to build first-party financial applications for Crypto.com users, but planned apps are not counted as live demand.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:what_it_is:1","claim:cronos:section:what_it_is:2"]},"what_happened":{"body":"Crypto.com gave Cronos an immediate distribution channel, and TVL peaked at $3.22 billion in April 2022. By 2026-08-03, TVL was $253.50 million, a 92.13% drawdown, with $179.54 million in dollar stablecoins. Thirty-day DEX volume was $39.91 million, down 67.35% from the prior provider comparison. Fees were $603,614.39 and retained revenue was $121,290.02. In 2025, governance restored a large CRO strategic reserve after the 2021 burn.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:what_happened:1","claim:cronos:section:what_happened:2"]},"why_this_outcome":{"body":"Crypto.com distribution was Cronos’ largest advantage, but a general-purpose EVM chain did not keep most of the 2022 capital cycle. Users could access similar DeFi products on larger networks, and current DEX volume is shrinking. The 70 billion CRO reserve reversal also weakened the scarcity story after the earlier burn and increased governance concentration. Cronos Labs now argues that first-party apps distributed through Crypto.com are a better strategy; that is a plausible response, not evidence of a completed turnaround.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:why_this_outcome:1","claim:cronos:section:why_this_outcome:2"]},"strategic_choices":{"body":"Cronos chose an EVM chain tied closely to Crypto.com distribution and an invitation-based validator model. Governance later reversed most of the 2021 burn by creating a strategic reserve with a long vesting schedule. Cronos Labs then shifted from selling generic blockspace toward first-party financial applications and proposed new staking and emission rules in 2026. Each step seeks stronger distribution or economics, but the supply reversal asks token holders to trust concentrated long-term stewardship.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:strategic_choices:1","claim:cronos:section:strategic_choices:2"]},"operating_model":{"body":"Cronos EVM uses proof-of-authority-style admission: validator participation is not simply open to any holder who stakes CRO. That can provide coordinated operations and known counterparties, but it concentrates censorship, upgrade and governance power. Crypto.com distribution is a commercial advantage rather than an independent security guarantee. The reviewed sources do not provide a current beneficial-owner map for validators or a complete separation of Cronos Labs, Crypto.com and partner control.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:operating_model:1","claim:cronos:section:operating_model:2"]},"token_and_value_capture":{"body":"CRO pays gas and supports staking and governance across the Cronos ecosystem. CoinGecko observed CRO at $0.054896, with a $2.60 billion market capitalization and $5.43 billion fully diluted value, about 93.84% below its recorded high. The restored strategic reserve greatly expanded the long-term supply overhang. Proposed emission decay and lock tiers may change staking incentives, but this review does not call them active until executed parameters and token flows are verified.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:token_and_value_capture:1","claim:cronos:section:token_and_value_capture:2"]},"counterfactual":{"body":"Cronos could have kept the 2021 burn intact, preserving scarcity while giving up a large treasury for incentives and strategic deals. It could also have focused on a small number of Crypto.com-native products from launch instead of competing as another general EVM chain. A more permissionless validator set would reduce control concentration while making coordination harder. The measurable test is whether new applications create paying demand that exceeds dilution and operating cost.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:counterfactual:1","claim:cronos:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The major risks are token dilution, concentrated governance, admitted validators, dependence on Crypto.com distribution and weak DeFi retention. Cronos’ umbrella branding can also cause analysts to mix EVM, POS and zkEVM activity. We lack repeat-user cohorts, an independent validator ownership map, a reconciled reserve unlock schedule and verified first-party app economics. Proposed economic changes should remain proposals until on-chain execution is confirmed.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:risks_and_unknowns:1","claim:cronos:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Cronos is operating but declining. It still holds meaningful capital and stablecoins, and Crypto.com remains a strong distribution channel. However, TVL is 92.13% below peak, monthly DEX flow is contracting and retained revenue is small compared with the token’s fully diluted value. The first-party app strategy may create a second act, but the lifecycle call changes only after those products produce durable users, fees and transparent value capture.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:lifecycle:1","claim:cronos:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is an active but smaller Crypto.com-linked chain while first-party finance products are built. The call improves if new apps launch, repeat users grow, fees and retained revenue rise, and reserve unlocks remain transparent. Watch CRO unlocks, validator entities, DEX liquidity, stablecoin balances, app-level revenue and whether proposed emissions become live. The call worsens if distribution produces promotional activity without durable cash flow or if supply growth overwhelms demand.","as_of":"2026-08-03","claim_ids":["claim:cronos:section:outlook_and_watch:1","claim:cronos:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:cronos:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":253500085,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:cronos:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:cronos:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":179541902.7834992,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:cronos:metric:stablecoins-latest"],"quality_flags":[]},{"id":"metric:cronos:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":39914574.99,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rol