WITH canonical_seed(payload) AS (VALUES ('{"chain":"Thorchain","sources":[{"id":"source:thorchain:overview","title":"THORChain documentation","url":"https://docs.thorchain.org/","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current native cross-chain AMM and network description."},{"id":"source:thorchain:technology","title":"THORChain technology","url":"https://docs.thorchain.org/technology","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Bifrost, threshold-signature vault and Cosmos SDK design."},{"id":"source:thorchain:tcy","title":"RUNE and TCY tokenomics","url":"https://docs.thorchain.org/tokenomics-rune-tcy","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current fee split and TCY income rights."},{"id":"source:thorchain:thorfi","title":"THORFi debt and TCY","url":"https://dev.thorchain.org/concepts/tcy.html","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"January 2025 suspension, approximate debt and conversion mechanism."},{"id":"source:thorchain:thorswap","title":"Protocol spotlight: THORSwap","url":"https://blog.thorchain.org/protocol-spotlight-thorswap/","publisher":"THORChain","published_at":"2026-02-27","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"THORSwap described as an independent frontend and aggregator."},{"id":"source:thorchain:laundering","title":"The blockchain fueling North Korea crypto laundering","url":"https://www.coindesk.com/tech/2025/04/07/the-blockchain-fueling-north-korea-s-massive-crypto-laundering-operation","publisher":"CoinDesk","published_at":"2025-04-07","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Independent reporting on illicit flow and interface-policy conflict."},{"id":"source:thorchain:tvl","title":"Thorchain historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Thorchain","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:thorchain:volume","title":"Thorchain DEX volume API","url":"https://api.llama.fi/overview/dexs/Thorchain?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:thorchain:fees","title":"Thorchain fees API","url":"https://api.llama.fi/overview/fees/Thorchain?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:thorchain:revenue","title":"Thorchain revenue API","url":"https://api.llama.fi/overview/fees/Thorchain?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:thorchain:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Thorchain row and peggedUSD field."},{"id":"source:thorchain:market","title":"Thorchain token market data","url":"https://api.coingecko.com/api/v3/coins/thorchain","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T19:24:23.300Z","observation_completed_at":"2026-08-03T19:24:34.000Z","provider":"DefiLlama and CoinGecko","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":28797048,"peak_tvl_usd":546437336,"peak_tvl_date":"2022-04-02","tvl_drawdown_pct":94.73,"dex_volume_30d_usd":765915393,"dex_volume_change_1m_pct":-35.97,"fees_30d_usd":187997,"revenue_30d_usd":13945.18,"creditor_boundary":"About $210 million of ThorFi claims were converted into TCY; this is not cash repayment."},"outcome":{"label":"declining","summary":"THORChain still processes meaningful native swaps, but TVL is 94.73% below peak and ThorFi’s roughly $210 million debt became a risky TCY fee claim. Network activity, frontend activity and creditor recovery are separate outcomes.","confidence":"high","as_of":"2026-08-03","source_refs":["source:thorchain:tvl","source:thorchain:volume","source:thorchain:fees","source:thorchain:revenue","source:thorchain:thorfi","source:thorchain:market"]},"why":{"summary":"The native-swap design solved a real distribution problem. ThorFi expanded into zero-interest, no-liquidation credit whose liabilities became unserviceable. TCY preserved operation by moving recovery into future fees rather than repaying cash.","confidence":"medium","source_refs":["source:thorchain:overview","source:thorchain:technology","source:thorchain:thorfi","source:thorchain:tcy","source:thorchain:volume","source:thorchain:revenue"]},"strategic_choices":[{"decision":"Build native cross-chain vaults and RUNE-paired pools.","consequence":"Users avoid wrapped assets while accepting validator-vault risk.","confidence":"high","source_refs":["source:thorchain:overview","source:thorchain:technology"]},{"decision":"Expand into ThorFi lending and Savers.","consequence":"The network added demand and unserviceable balance-sheet liabilities.","confidence":"high","source_refs":["source:thorchain:thorfi"]},{"decision":"Convert claims into TCY with 10% of network income.","consequence":"Operation continued while creditors took long-dated recovery risk.","confidence":"high","source_refs":["source:thorchain:tcy","source:thorchain:thorfi"]}],"counterfactual":{"summary":"Remaining swap-only would avoid ThorFi credit losses. Explicit interest and liquidations might price risk better. Transparent fee income and TCY distributions now determine recovery.","confidence":"medium","source_refs":["source:thorchain:overview","source:thorchain:thorfi","source:thorchain:tcy"]},"watch":[{"signal":"Liquidity, swap volume, fees, retained revenue and TCY distributions.","implication":"Sustainable economics would support both security and creditor recovery.","source_refs":["source:thorchain:tvl","source:thorchain:volume","source:thorchain:fees","source:thorchain:revenue","source:thorchain:tcy"]},{"signal":"Vault incidents, validator entities, frontend route share and illicit-flow controls.","implication":"Reliable custody and clear control boundaries would reduce operational risk.","source_refs":["source:thorchain:technology","source:thorchain:thorswap","source:thorchain:laundering"]}],"unknowns":[{"question":"How much value have TCY holders actually recovered?","resolution_trigger":"A reconciled distribution ledger in RUNE and USD."},{"question":"Who beneficially owns current validators?","resolution_trigger":"An independent entity-level validator map."},{"question":"What share of flow comes from each frontend?","resolution_trigger":"A non-overlapping route attribution study."},{"question":"What are net network costs after every fee allocation?","resolution_trigger":"A complete protocol cash-flow reconciliation."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Thorchain

