-- canonical-profile-start Thorchain
INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Thorchain',
  'The swap network solved a real problem and still carries substantial flow through wallets and aggregators. ThorFi took a different risk: zero-interest, no-liquidation lending depended on RUNE economics and created liabilities the system could not service after market stress. TCY socialized those claims into future network income, preserving operation but transferring recovery risk to creditors. Illicit-flow scrutiny also exposed a conflict between a permissionless base protocol and frontends that can filter access.',
  'bearish',
  'THORChain is operating but declining. The core swap network still processed $765.92 million in 30 days, which is meaningful product use. At the same time, TVL is 94.73% below peak, RUNE is almost 98% below its high and ThorFi creditors were converted into a long-dated fee claim. The network survived the crisis, but survival is not creditor repayment and high flow is not proof of healthy economics.',
  '2026-08-03',
  '[{"id":"source:thorchain:overview","title":"THORChain documentation","url":"https://docs.thorchain.org/","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current native cross-chain AMM and network description."},{"id":"source:thorchain:technology","title":"THORChain technology","url":"https://docs.thorchain.org/technology","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Bifrost, threshold-signature vault and Cosmos SDK design."},{"id":"source:thorchain:tcy","title":"RUNE and TCY tokenomics","url":"https://docs.thorchain.org/tokenomics-rune-tcy","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current fee split and TCY income rights."},{"id":"source:thorchain:thorfi","title":"THORFi debt and TCY","url":"https://dev.thorchain.org/concepts/tcy.html","publisher":"THORChain","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"January 2025 suspension, approximate debt and conversion mechanism."},{"id":"source:thorchain:thorswap","title":"Protocol spotlight: THORSwap","url":"https://blog.thorchain.org/protocol-spotlight-thorswap/","publisher":"THORChain","published_at":"2026-02-27","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"THORSwap described as an independent frontend and aggregator."},{"id":"source:thorchain:laundering","title":"The blockchain fueling North Korea crypto laundering","url":"https://www.coindesk.com/tech/2025/04/07/the-blockchain-fueling-north-korea-s-massive-crypto-laundering-operation","publisher":"CoinDesk","published_at":"2025-04-07","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Independent reporting on illicit flow and interface-policy conflict."},{"id":"source:thorchain:tvl","title":"Thorchain historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Thorchain","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:thorchain:volume","title":"Thorchain DEX volume API","url":"https://api.llama.fi/overview/dexs/Thorchain?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:thorchain:fees","title":"Thorchain fees API","url":"https://api.llama.fi/overview/fees/Thorchain?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:thorchain:revenue","title":"Thorchain revenue API","url":"https://api.llama.fi/overview/fees/Thorchain?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:thorchain:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Thorchain row and peggedUSD field."},{"id":"source:thorchain:market","title":"Thorchain token market data","url":"https://api.coingecko.com/api/v3/coins/thorchain","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:thorchain","type":"blockchain","slug":"thorchain","name":"THORChain","aliases":[]},"classification":{"subtype":"cross-chain liquidity layer 1","tags":["cosmos_sdk","cross_chain_amm","threshold_signatures","thorfi_restructuring"],"chains":[],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:thorchain:status"]},"outcome":{"label":"declining","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:thorchain:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"THORChain is a sovereign network for swapping native assets across blockchains without wrapping them into one host chain. Validators jointly control threshold-signature vaults, and liquidity pools pair assets with RUNE. Wallets and interfaces such as THORSwap route users into the protocol, but they are separate businesses and control their own screens. The base network, its frontends and the failed ThorFi savings and lending products must be evaluated separately.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:what_it_is:1","claim:thorchain:section:what_it_is:2"]},"what_happened":{"body":"THORChain became a major cross-chain swap backend, then suffered a severe ThorFi liability crisis. Lending and Savers withdrawals were suspended on January 23, 2025 with about $210 million of unserviceable debt. Governance converted claims into 210 million TCY tokens that receive 10% of network income in RUNE; that is a restructuring, not cash repayment. By 2026-08-03, TVL was $28.80 million, 94.73% below peak, while 30-day swap volume remained $765.92 million.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:what_happened:1","claim:thorchain:section:what_happened:2"]},"why_this_outcome":{"body":"The swap network solved a real problem and still carries substantial flow through wallets and aggregators. ThorFi took a different risk: zero-interest, no-liquidation lending depended on RUNE economics and created liabilities the system could not service after market stress. TCY socialized those claims into future network income, preserving operation but transferring recovery risk to creditors. Illicit-flow scrutiny also exposed a conflict between a permissionless base protocol and frontends that can filter access.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:why_this_outcome:1","claim:thorchain:section:why_this_outcome:2"]},"strategic_choices":{"body":"THORChain chose native cross-chain vaults and RUNE-paired liquidity rather than wrapped assets or a single bridge. It expanded from swaps into ThorFi lending and Savers, accepting balance-sheet risk to create more demand. After the crisis, governance issued TCY and redirected 10% of network income to holders instead of forcing immediate liquidation or cash redemption. Frontends remain independent, which preserves open infrastructure while making policy and sanctions responses uneven.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:strategic_choices:1","claim:thorchain:section:strategic_choices:2"]},"operating_model":{"body":"THORChain is built with Cosmos SDK. An active validator set uses threshold signatures to manage chain-specific vaults while Bifrost observes external chains. This removes a single custodian but concentrates risk in validator selection, signer software, vault operations and external-chain assumptions. Wallets and frontends can block or warn users, yet they do not rewrite base protocol rules. Volume routed by those interfaces is still protocol volume and must not be added twice.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:operating_model:1","claim:thorchain:section:operating_model:2"]},"token_and_value_capture":{"body":"RUNE secures the network, pairs with pool assets and absorbs protocol economics. CoinGecko observed RUNE at $0.443779, with a $150.15 million market capitalization and $157.22 million fully diluted value, about 97.87% below its recorded high. Current fee policy assigns 10% of network income to TCY holders, reducing what remains for nodes, liquidity and other uses. TCY has no governance rights and represents a risky fee claim, not a stablecoin or guaranteed creditor payout.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:token_and_value_capture:1","claim:thorchain:section:token_and_value_capture:2"]},"counterfactual":{"body":"THORChain could have remained a swap-only network and avoided ThorFi credit liabilities, giving up potential demand but protecting the core balance sheet. Lending could also have used liquidations and explicit interest to price risk, reducing borrower appeal while limiting hidden insolvency. After the crisis, liquidation might have closed claims faster but risked network failure. Durable fee income and transparent TCY distributions are now the observable recovery test.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:counterfactual:1","claim:thorchain:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are vault compromise, validator concentration, external-chain failures, thin liquidity, illicit-flow policy conflict and the continuing TCY burden. Reported swap volume is not profit, and low retained revenue limits the income available for security and creditors. We lack a complete creditor recovery ledger, current validator ownership map, interface-level flow split and independently reconciled network costs. A frontend restriction should never be described as a base-protocol shutdown.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:risks_and_unknowns:1","claim:thorchain:section:risks_and_unknowns:2"]},"lifecycle":{"body":"THORChain is operating but declining. The core swap network still processed $765.92 million in 30 days, which is meaningful product use. At the same time, TVL is 94.73% below peak, RUNE is almost 98% below its high and ThorFi creditors were converted into a long-dated fee claim. The network survived the crisis, but survival is not creditor repayment and high flow is not proof of healthy economics.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:lifecycle:1","claim:thorchain:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a still-useful cross-chain swap backend carrying a damaged credit and token history. The call improves if liquidity stabilizes, fees grow, validator control broadens and TCY distributions create transparent creditor recovery without starving security. Watch vault incidents, RUNE depth, route concentration, frontend policy, illicit-flow controls, TCY payouts and retained revenue. The call worsens if another balance-sheet product fails or if low liquidity makes vault and token reflexivity more dangerous.","as_of":"2026-08-03","claim_ids":["claim:thorchain:section:outlook_and_watch:1","claim:thorchain:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:thorchain:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":28797048,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:thorchain:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:thorchain:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"Native cross-chain swap volume (30d)","value":765915393,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:thorchain:metric:dex-volume-30d"],"quality_flags":["not_unique_users","frontend_routes_overlap"]},{"id":"metric:thorchain:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":187997,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:thorchain:metric:fees-30d"],"quality_flags":[]},{"id":"metric:thorchain:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":13945.18,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:thorchain:metric:revenue-30d"],"quality_flags":["gross_fees_not_profit"]},{"id":"metric:thorchain:token-price:2026-08-03","dimension":"token_price","label":"RUNE price","value":0.443779,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"current_price.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:thorchain:metric:token-price"],"quality_flags":[]},{"id":"metric:thorchain:token-market-cap:2026-08-03","dimension":"token_market_cap","label":"RUNE market capitalization","value":150150045,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"market_cap.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:thorchain:metric:token-market-cap"],"quality_flags":[]},{"id":"metric:thorchain:token-fdv:2026-08-03","dimension":"token_fdv","label":"RUNE fully diluted value","value":157216866,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"fully_diluted_valuation.usd.","scope":{"product":"blockcha