thorchain:thorfi","title":"THORFi debt and TCY","url":"https://dev.thorchain.org/concepts/tcy.html","publisher":"THORChain","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"January 2025 suspension, approximate debt and conversion mechanism."},{"id":"source:thorchain:thorswap","title":"Protocol spotlight: THORSwap","url":"https://blog.thorchain.org/protocol-spotlight-thorswap/","publisher":"THORChain","published_at":"2026-02-27","accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"THORSwap described as an independent frontend and aggregator."},{"id":"source:thorchain:laundering","title":"The blockchain fueling North Korea crypto laundering","url":"https://www.coindesk.com/tech/2025/04/07/the-blockchain-fueling-north-korea-s-massive-crypto-laundering-operation","publisher":"CoinDesk","published_at":"2025-04-07","accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Independent reporting on illicit flow and interface-policy conflict."},{"id":"source:thorchain:tvl","title":"Thorchain historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Thorchain","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:thorchain:volume","title":"Thorchain DEX volume API","url":"https://api.llama.fi/overview/dexs/Thorchain?dataType=dailyVolume","publisher":"DefiLlama","p