he review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:overview","source:thorchain:tvl","source:thorchain:volume"],"evidence_locator":"Current protocol documentation and nonzero swap flow show an operating network.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:outcome","field_path":"outcome.label","assertion":"THORChain is classified declining as of 2026-08-03.","value":"declining","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:thorchain:tvl","source:thorchain:volume","source:thorchain:fees","source:thorchain:revenue","source:thorchain:thorfi","source:thorchain:market"],"evidence_locator":"Swap activity, capital, economics, token and the ThorFi creditor event were reviewed together.","support_direction":"supports","note":"Analyst lifecycle classification; current metrics do not prove a single cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"THORChain uses validator-controlled vaults and RUNE-paired pools for native cross-chain swaps.","value":"THORChain uses validator-controlled vaults and RUNE-paired pools for native cross-chain swaps.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:overview","source:thorchain:technology"],"evidence_locator":"Current protocol and technology descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"THORSwap is an independent frontend rather than the THORChain network itself.","value":"THORSwap is an independent frontend rather than the THORChain network itself.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:thorswap"],"evidence_locator":"Dated protocol spotlight.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"ThorFi lending and savings faced about $210 million of unserviceable debt and suspended withdrawals in January 2025.","value":210000000,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:thorfi"],"evidence_locator":"Current debt and suspension history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"TCY converted claims into a 10% network-income right rather than immediate repayment.","value":"TCY converted claims into a 10% network-income right rather than immediate repayment.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:tcy","source:thorchain:thorfi"],"evidence_locator":"TCY issuance and revenue-share terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"ThorFi design created liabilities that became unserviceable after market stress.","value":"ThorFi design created liabilities that became unserviceable after market stress.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:thorchain:thorfi"],"evidence_locator":"Protocol explanation of the crisis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Current volume shows swap demand but not creditor recovery or frontend independence.","value":"Current volume shows swap demand but not creditor recovery or frontend independence.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:thorchain:volume","source:thorchain:tcy","source:thorchain:thorswap"],"evidence_locator":"Separate flow, claim and interface evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"THORChain chose validator vaults and RUNE-paired pools for cross-chain settlement.","value":"THORChain chose validator vaults and RUNE-paired pools for cross-chain settlement.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:technology","source:thorchain:overview"],"evidence_locator":"Current mechanism.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Governance chose TCY revenue sharing to restructure ThorFi claims.","value":"Governance chose TCY revenue sharing to restructure ThorFi claims.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:tcy","source:thorchain:thorfi"],"evidence_locator":"Debt conversion and fee split.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Validators use threshold signatures and Bifrost to manage and observe cross-chain vaults.","value":"Validators use threshold signatures and Bifrost to manage and observe cross-chain vaults.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:technology"],"evidence_locator":"Current architecture.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Frontend filtering and base-protocol permissionlessness are different control layers.","value":"Frontend filtering and base-protocol permissionlessness are different control layers.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:thorswap","source:thorchain:laundering"],"evidence_locator":"Operator boundary and independent risk reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"RUNE market capitalization was $150,150,045 at the observation date.","value":150150045,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:market"],"evidence_locator":"CoinGecko market_data.market_cap.usd.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"TCY receives 10% of network income and does not provide governance rights or guaranteed repayment.","value":"TCY receives 10% of network income and does not provide governance rights or guaranteed repayment.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:tcy","source:thorchain:thorfi"],"evidence_locator":"Current TCY rights and limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"A swap-only scope would avoid ThorFi credit risk while limiting product expansion.","value":"A swap-only scope would avoid ThorFi credit risk while limiting product expansion.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:thorchain:overview","source:thorchain:thorfi"],"evidence_locator":"Core protocol versus failed product scope.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Priced and collateral-enforced lending could reduce insolvency risk while changing the product promise.","value":"Priced and collateral-enforced lending could reduce insolvency risk while changing the product promise.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:thorchain:thorfi"],"evidence_locator":"Documented lending design and failure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Vault, signer and external-chain failures remain core technical risks.","value":"Vault, signer and external-chain failures remain core technical risks.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:technology"],"evidence_locator":"Current vault architecture.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Creditor recovery, validator ownership and net network costs remain unresolved.","value":"Creditor recovery, validator ownership and net network costs remain unresolved.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:thorchain:tcy","source:thorchain:fees","source:thorchain:revenue"],"evidence_locator":"Current sources do not fully reconcile them.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"THORChain remains active with $765.92 million in 30-day swap volume.","value":"THORChain remains active with $765.92 million in 30-day swap volume.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:thorchain:volume","source:thorchain:overview"],"evidence_locator":"Current provider and protocol observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"Capital, token and creditor outcomes support a declining lifecycle call.","value":"Capital, token and creditor outcomes support a declining lifecycle call.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:thorchain:tvl","source:thorchain:market","source:thorchain:thorfi"],"evidence_locator":"Peak-to-current and restructuring evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorchain:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Stable liquidity, fee income and transparent TCY payouts would strengthen the outlook.","value":"Stable liquidity, fee income and transparent TCY payouts would strengthen the outlook.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:thorchain:tvl","source:thorchain:fees","source:thorchain:tcy"],"evidence_locator":"Current baseline for future review.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:thorc