"2025-05-01","as_of":"2025-05-01","confidence":"high","kind":"fact","source_ids":["source:thorchain:tcy","source:thorchain:thorfi"],"evidence_locator":"Token mechanics and launch-period history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T19:24:34.000Z","next_review_at":"2026-08-10T19:24:34.000Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":[]},"extensions":{"legacy_origin":"chain_analysis_and_chain_facts","observation_window":{"started_at":"2026-08-03T19:24:23.300Z","completed_at":"2026-08-03T19:24:34.000Z"},"explicit_unknowns":[["How much value have TCY holders actually recovered?","A reconciled distribution ledger in RUNE and USD."],["Who beneficially owns current validators?","An independent entity-level validator map."],["What share of flow comes from each frontend?","A non-overlapping route attribution study."],["What are net network costs after every fee allocation?","A complete protocol cash-flow reconciliation."]],"methodology_notes":["Every material field has atomic pending claims; a person must review those claims before publication.","TVL, stablecoin supply, DEX volume, fees, revenue and token prices answer different questions and must not be treated as interchangeable.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate."]}}}'
)
ON CONFLICT(chain) DO UPDATE SET
  updated_at = excluded.updated_at,
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(chain_analysis.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(excluded.sources, '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(chain_analysis.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(excluded.sources, '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(chain_analysis.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  profile = json_set(
    COALESCE(chain_analysis.profile, '{}'),
    '$.canonical_profile', json_extract(excluded.profile, '$.canonical_profile')
  );
-- canonical-profile-end Thorchain

