WITH canonical_seed(payload) AS (VALUES ('{"chain":"Abstract","sources":[{"id":"source:abstract:overview","title":"What is Abstract","url":"https://docs.abs.xyz/what-is-abstract","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current ZK Stack Ethereum rollup description."},{"id":"source:abstract:accounts","title":"Abstract native account abstraction","url":"https://docs.abs.xyz/how-abstract-works/native-account-abstraction","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Native account and paymaster behavior."},{"id":"source:abstract:wallet","title":"Abstract Global Wallet architecture","url":"https://docs.abs.xyz/abstract-global-wallet/architecture","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Privy signer, contract-wallet and recovery architecture."},{"id":"source:abstract:portal","title":"Abstract Portal overview","url":"https://docs.abs.xyz/portal/overview","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Portal discovery, wallet, XP, streaming and trading features."},{"id":"source:abstract:l2beat","title":"Abstract risk analysis","url":"https://l2beat.com/scaling/projects/abstract","publisher":"L2BEAT","source_role":"independent","tier":"A","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current stage, operator, upgrade and liveness incident panels."},{"id":"source:abstract:tvl","title":"Abstract historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Abstract","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:abstract:volume","title":"Abstract DEX volume API","url":"https://api.llama.fi/overview/dexs/Abstract?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:abstract:fees","title":"Abstract fees API","url":"https://api.llama.fi/overview/fees/Abstract?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:abstract:revenue","title":"Abstract revenue API","url":"https://api.llama.fi/overview/fees/Abstract?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:abstract:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Abstract row and peggedUSD field."}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T19:24:23.300Z","observation_completed_at":"2026-08-03T19:24:34.000Z","provider":"DefiLlama and L2BEAT","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":10214276,"peak_tvl_usd":57839558,"peak_tvl_date":"2025-08-14","tvl_drawdown_pct":82.34,"stablecoin_supply":{"pegged_usd":6858504.882522769},"dex_volume_30d_usd":15252805,"dex_volume_change_1m_pct":-6.55,"fees_30d_usd":2875241.97,"revenue_30d_usd":785923.19,"product_boundary":"Portal, Global Wallet, XP and streaming are not counted as chain transactions without reconciliation."},"outcome":{"label":"middling","summary":"Abstract is a small but differentiated consumer rollup. Native accounts, Global Wallet and Portal are live, yet TVL is 82.34% below peak and control remains Stage 0. Product engagement and chain activity stay separate.","confidence":"medium","as_of":"2026-08-03","source_refs":["source:abstract:tvl","source:abstract:volume","source:abstract:fees","source:abstract:revenue","source:abstract:l2beat","source:abstract:portal"]},"why":{"summary":"Abstract built a coordinated consumer funnel rather than selling generic blockspace. That can reduce onboarding friction and support fees, but it concentrates distribution and wallet dependencies while capital and DEX activity remain small.","confidence":"medium","source_refs":["source:abstract:overview","source:abstract:accounts","source:abstract:wallet","source:abstract:portal","source:abstract:l2beat","source:abstract:tvl","source:abstract:fees"]},"strategic_choices":[{"decision":"Build a ZK Stack Ethereum rollup.","consequence":"Abstract controls execution while assuming rollup operator risk.","confidence":"high","source_refs":["source:abstract:overview","source:abstract:l2beat"]},{"decision":"Make account abstraction native.","consequence":"Apps can sponsor gas and simplify accounts while users depend on wallet infrastructure.","confidence":"high","source_refs":["source:abstract:accounts","source:abstract:wallet"]},{"decision":"Operate Portal as a first-party discovery funnel.","consequence":"Distribution improves while ecosystem attention becomes curated and concentrated.","confidence":"high","source_refs":["source:abstract:portal"]}],"counterfactual":{"summary":"A rollup-only strategy would reduce product scope but lose the consumer funnel. A chain-neutral portal would avoid rollup risk but surrender execution control. Repeat paying users are the practical test.","confidence":"medium","source_refs":["source:abstract:overview","source:abstract:portal","source:abstract:l2beat"]},"watch":[{"signal":"Repeat paying users, app concentration, TVL, fees and retained revenue.","implication":"Broad persistence would show durable demand beyond Portal engagement.","source_refs":["source:abstract:tvl","source:abstract:fees","source:abstract:revenue","source:abstract:portal"]},{"signal":"Sequencer, prover, upgrade, Privy and recovery incidents.","implication":"Reliable operation and broader controls would reduce current platform risk.","source_refs":["source:abstract:l2beat","source:abstract:wallet"]}],"unknowns":[{"question":"How many Portal users become repeat on-chain payers?","resolution_trigger":"A reconciled two-quarter funnel cohort."},{"question":"Which applications produce most fees?","resolution_trigger":"A non-overlapping app-level fee statement."},{"question":"What are complete operator and incentive costs?","resolution_trigger":"An audited rollup and product income statement."},{"question":"Who controls sequencer, prover and upgrades by beneficial owner?","resolution_trigger":"An independent entity-level control map."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Abstract

