-- canonical-profile-start Abstract
INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Abstract',
  'Abstract made onboarding and discovery the product, not just cheaper blockspace. Native account abstraction, a global wallet and Portal can make consumer apps easier to enter and revisit. That likely helps explain why the chain can generate meaningful fees with little TVL. However, the capital base and DEX volume remain small, and Portal engagement cannot substitute for verified repeat on-chain users. The result is a promising but concentrated consumer distribution experiment rather than a proven broad ecosystem.',
  'mixed',
  'Abstract is operating and middling. It has shipped the chain, native accounts, Global Wallet and Portal, and it generated meaningful fees. Capital is still 82.34% below peak, stablecoins and DEX volume are small, and current control remains Stage 0. The next lifecycle test is whether consumer distribution produces repeat paying users across several applications without recurring liveness incidents or dependence on one curated interface.',
  '2026-08-03',
  '[{"id":"source:abstract:overview","title":"What is Abstract","url":"https://docs.abs.xyz/what-is-abstract","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current ZK Stack Ethereum rollup description."},{"id":"source:abstract:accounts","title":"Abstract native account abstraction","url":"https://docs.abs.xyz/how-abstract-works/native-account-abstraction","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Native account and paymaster behavior."},{"id":"source:abstract:wallet","title":"Abstract Global Wallet architecture","url":"https://docs.abs.xyz/abstract-global-wallet/architecture","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Privy signer, contract-wallet and recovery architecture."},{"id":"source:abstract:portal","title":"Abstract Portal overview","url":"https://docs.abs.xyz/portal/overview","publisher":"Abstract","source_role":"primary","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Portal discovery, wallet, XP, streaming and trading features."},{"id":"source:abstract:l2beat","title":"Abstract risk analysis","url":"https://l2beat.com/scaling/projects/abstract","publisher":"L2BEAT","source_role":"independent","tier":"A","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Current stage, operator, upgrade and liveness incident panels."},{"id":"source:abstract:tvl","title":"Abstract historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Abstract","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:abstract:volume","title":"Abstract DEX volume API","url":"https://api.llama.fi/overview/dexs/Abstract?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:abstract:fees","title":"Abstract fees API","url":"https://api.llama.fi/overview/fees/Abstract?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:abstract:revenue","title":"Abstract revenue API","url":"https://api.llama.fi/overview/fees/Abstract?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"total30d field."},{"id":"source:abstract:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T19:24:34.000Z","evidence_locator":"Abstract row and peggedUSD field."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:abstract","type":"blockchain","slug":"abstract","name":"Abstract","aliases":[]},"classification":{"subtype":"consumer-focused Ethereum ZK rollup","tags":["zk_stack","ethereum","account_abstraction","consumer_apps"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:abstract:status"]},"outcome":{"label":"middling","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"medium","claim_ids":["claim:abstract:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Abstract is an Ethereum ZK rollup built with the ZK Stack and aimed at consumer applications. It uses ETH for gas and has no separate chain token in the reviewed sources. The operator also runs Abstract Portal and Abstract Global Wallet, which package discovery, accounts, XP, streaming and trading into a consumer interface. Those products may distribute users, but their clicks and XP are not automatically chain transactions or retained protocol demand.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:what_it_is:1","claim:abstract:section:what_it_is:2"]},"what_happened":{"body":"Abstract launched mainnet in January 2025 around the thesis that better accounts and consumer discovery could reduce crypto friction. TVL peaked at $57.84 million in August 2025 and fell to $10.21 million by 2026-08-03, an 82.34% drawdown. Dollar stablecoins were $6.86 million and 30-day DEX volume was $15.25 million, down 6.55% from the prior provider comparison. Fees were $2.88 million and provider-reported retained revenue was $785,923.19.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:what_happened:1","claim:abstract:section:what_happened:2"]},"why_this_outcome":{"body":"Abstract made onboarding and discovery the product, not just cheaper blockspace. Native account abstraction, a global wallet and Portal can make consumer apps easier to enter and revisit. That likely helps explain why the chain can generate meaningful fees with little TVL. However, the capital base and DEX volume remain small, and Portal engagement cannot substitute for verified repeat on-chain users. The result is a promising but concentrated consumer distribution experiment rather than a proven broad ecosystem.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:why_this_outcome:1","claim:abstract:section:why_this_outcome:2"]},"strategic_choices":{"body":"Abstract chose a ZK Stack rollup, native account abstraction and a first-party consumer portal. Global Wallet combines an embedded Privy signer with a smart-account layer so users can recover accounts and applications can sponsor gas. Portal then bundles discovery, XP, streaming and trading around those accounts. The choices create a strong funnel, but they also make the ecosystem dependent on the operator, Privy and a curated interface rather than only the open chain.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:strategic_choices:1","claim:abstract:section:strategic_choices:2"]},"operating_model":{"body":"Abstract batches transactions through operator-controlled rollup infrastructure and settles to Ethereum with ZK proofs. L2BEAT classified it Stage 0 at the review date and identified centralized operator and emergency-upgrade risks. In May 2025, an unprovable batch halted finalization for about two days and was resolved through an emergency upgrade. Account and Portal convenience therefore sit on top of material sequencer, prover, upgrade and wallet-provider dependencies.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:operating_model:1","claim:abstract:section:operating_model:2"]},"token_and_value_capture":{"body":"Abstract uses ETH for gas and no separate chain token was verified. That avoids a token whose price can obscure product adoption, but it also means value capture must be judged through fees, retained revenue and ecosystem ownership rather than a chain-token market capitalization. Current 30-day fees were high relative to TVL, yet the provider’s retained-revenue field is not operator profit and does not include all infrastructure, wallet or incentive costs.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:token_and_value_capture:1","claim:abstract:section:token_and_value_capture:2"]},"counterfactual":{"body":"Abstract could have launched only the rollup and left wallet and discovery to independent teams, reducing operator concentration while losing a coordinated consumer funnel. It could also have deployed Portal and Global Wallet across existing chains, avoiding rollup operations but giving up control over execution and economics. The useful comparison is whether the integrated stack creates more retained paying users than a chain-neutral consumer application would.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:counterfactual:1","claim:abstract:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The main risks are operator concentration, emergency upgrades, prover failures, Privy or wallet dependency, curated distribution and weak capital depth. Portal XP or streaming numbers could become vanity metrics if they are not reconciled with paying on-chain behavior. We lack repeat-user cohorts, application-level fee concentration, complete operator costs and an independent control map. The May 2025 halt shows that user-facing polish does not remove settlement and liveness risk.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:risks_and_unknowns:1","claim:abstract:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Abstract is operating and middling. It has shipped the chain, native accounts, Global Wallet and Portal, and it generated meaningful fees. Capital is still 82.34% below peak, stablecoins and DEX volume are small, and current control remains Stage 0. The next lifecycle test is whether consumer distribution produces repeat paying users across several applications without recurring liveness incidents or dependence on one curated interface.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:lifecycle:1","claim:abstract:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is a small consumer rollup with a differentiated onboarding funnel but concentrated control. The call improves if repeat users and paying applications grow, fees diversify, TVL stabilizes and operator safeguards mature. Watch account recovery failures, Privy dependence, app and fee concentration, Portal-to-chain conversion, sequencer or prover incidents and upgrade controls. The call worsens if engagement stays inside XP and content surfaces without durable on-chain demand.","as_of":"2026-08-03","claim_ids":["claim:abstract:section:outlook_and_watch:1","claim:abstract:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:abstract:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":10214276,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:abstract:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:abstract:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":6858504.882522769,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:abstract:metric:stablecoins-latest"],"quality_flags":[]},{"id":"metric:abstract:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":15252805,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:abstract:metric:dex-volume-30d"],"quality_flags":["not_unique_users","portal_activity_excluded"]},{"id":"metric:abstract:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":2875241.97,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:abstract:metric:fees-30d"],"quality_flags":[]},{"id":"metric:abstract:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":785923.19,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:abstract:metric:revenue-30d"],"quality_flags":["gross_fees_not_profit"]}],"events":[{"id":"event:abstract:mainnet","type":"launch","date":"2025-01-27","description":"Abstract mainnet launched.","claim_ids":["claim:abstract:event:mainnet"]},{"id":"event:abstract:liveness","type":"incident","date":"2025-05-14","description":"An unprovable batch halted Abstract finalization for about two days.","claim_ids":["claim:abstract:event:liveness"]},{"id":"event:abstract:peak-tvl","type":"market_event","date":"2025-08-14","description":"Abstract reached the maximum TVL point in the reviewed series.","claim_ids":["claim:abstract:event:peak-tvl"]}],"sources":[{"id":"source:abstract:overview","title":"What is Abstract","url":"https://docs.abs.xyz/what-is-abstract","publisher":"Abstract","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Current ZK Stack Ethereum rollup description."},{"id":"source:abstract:accounts","title":"Abstract native account abstraction","url":"https://docs.abs.xyz/how-abstract-works/native-account-abstraction","publisher":"Abstract","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Native account and paymaster behavior."},{"id":"source:abstract:wallet","title":"Abstract Global Wallet architecture","url":"https://docs.abs.xyz/abstract-global-wallet/architecture","publisher":"Abstract","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Privy signer, contract-wallet and recovery architecture."},{"id":"source:abstract:portal","title":"Abstract Portal overview","url":"https://docs.abs.xyz/portal/overview","publisher":"Abstract","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Portal discovery, wallet, XP, streaming and trading features."},{"id":"source:abstract:l2beat","title":"Abstract risk analysis","url":"https://l2beat.com/scaling/projects/abstract","publisher":"L2BEAT","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Current stage, operator, upgrade and liveness incident panels."},{"id":"source:abstract:tvl","title":"Abstract historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Abstract","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:abstract:volume","title":"Abstract DEX volume API","url":"https://api.llama.fi/overview/dexs/Abstract?dataType=dailyVolume","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"total30d and change_1m fields."},{"id":"source:abstract:fees","title":"Abstract fees API","url":"https://api.llama.fi/overview/fees/Abstract?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"total30d field."},{"id":"source:abstract:revenue","title":"Abstract revenue API","url":"https://api.llama.fi/overview/fees/Abstract?dataType=dailyRevenue","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"total30d field."},{"id":"source:abstract:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:24:34.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:24:34.000Z","content_hash":null,"evidence_locator":"Abstract row and peggedUSD field."}],"claims":[{"id":"claim:abstract:status","field_path":"status.operating_state","assertion":"Abstract was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:overview","source:abstract:l2beat","source:abstract:tvl"],"evidence_locator":"Current network documentation, risk panels and nonzero capital show an operating rollup.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:outcome","field_path":"outcome.label","assertion":"Abstract is classified middling as of 2026-08-03.","value":"middling","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:abstract:tvl","source:abstract:volume","source:abstract:fees","source:abstract:revenue","source:abstract:l2beat","source:abstract:portal"],"evidence_locator":"Chain capital and economics were reviewed separately from Portal and wallet distribution.","support_direction":"supports","note":"Analyst lifecycle classification; current metrics do not prove a single cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Abstract is an Ethereum ZK rollup using ETH for gas.","value":"Abstract is an Ethereum ZK rollup using ETH for gas.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:overview","source:abstract:l2beat"],"evidence_locator":"Current architecture and gas panels.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Portal and Global Wallet are distribution products distinct from rollup execution.","value":"Portal and Global Wallet are distribution products distinct from rollup execution.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:portal","source:abstract:wallet"],"evidence_locator":"Product and wallet architecture.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Abstract launched mainnet in January 2025 as a consumer-focused ZK rollup.","value":"Abstract launched mainnet in January 2025 as a consumer-focused ZK rollup.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:overview","source:abstract:l2beat"],"evidence_locator":"Current project history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"TVL fell from $57,839,558 to $10,214,276 by the review date.","value":"peak 57839558; latest 10214276","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:tvl"],"evidence_locator":"Maximum and latest series points.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Account abstraction and Portal plausibly reduce onboarding and discovery friction.","value":"Account abstraction and Portal plausibly reduce onboarding and discovery friction.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:abstract:accounts","source:abstract:wallet","source:abstract:portal"],"evidence_locator":"Current product design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Portal engagement cannot be converted into chain retention without reconciled user cohorts.","value":"Portal engagement cannot be converted into chain retention without reconciled user cohorts.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:abstract:portal","source:abstract:volume"],"evidence_locator":"Product activity and aggregate chain flow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Abstract chose native account abstraction and paymaster support.","value":"Abstract chose native account abstraction and paymaster support.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:accounts"],"evidence_locator":"Current account design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Global Wallet and Portal create a first-party distribution funnel with Privy dependency.","value":"Global Wallet and Portal create a first-party distribution funnel with Privy dependency.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:wallet","source:abstract:portal"],"evidence_locator":"Wallet architecture and Portal scope.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Abstract remained Stage 0 with centralized operator and emergency-upgrade risk.","value":"Abstract remained Stage 0 with centralized operator and emergency-upgrade risk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:l2beat"],"evidence_locator":"Current stage and risk panels.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"A May 2025 unprovable batch halted finalization for about two days.","value":"A May 2025 unprovable batch halted finalization for about two days.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:l2beat"],"evidence_locator":"Liveness incident panel.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Abstract uses ETH for gas and no separate chain token was verified.","value":"Abstract uses ETH for gas and no separate chain token was verified.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:overview","source:abstract:l2beat"],"evidence_locator":"Current gas and project descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Provider-reported retained revenue is not a complete operator profit measure.","value":"Provider-reported retained revenue is not a complete operator profit measure.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:abstract:fees","source:abstract:revenue"],"evidence_locator":"Gross and retained provider fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"A rollup-only approach would reduce first-party distribution while lowering operator scope.","value":"A rollup-only approach would reduce first-party distribution while lowering operator scope.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:abstract:overview","source:abstract:portal"],"evidence_locator":"Chain versus Portal product boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"A chain-neutral portal could avoid rollup operations while giving up execution control.","value":"A chain-neutral portal could avoid rollup operations while giving up execution control.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:abstract:portal","source:abstract:l2beat"],"evidence_locator":"Integrated product and rollup risk.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Operator, prover, upgrade and wallet-provider dependencies remain material.","value":"Operator, prover, upgrade and wallet-provider dependencies remain material.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:l2beat","source:abstract:wallet"],"evidence_locator":"Current rollup and account controls.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Repeat paying users, app concentration and full operator costs remain unresolved.","value":"Repeat paying users, app concentration and full operator costs remain unresolved.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:abstract:portal","source:abstract:fees","source:abstract:revenue"],"evidence_locator":"Current sources omit those measurements.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"Abstract has live rollup, account, wallet and Portal products.","value":"Abstract has live rollup, account, wallet and Portal products.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:abstract:overview","source:abstract:accounts","source:abstract:wallet","source:abstract:portal"],"evidence_locator":"Current shipped product descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"Shipped products and meaningful fees coexist with low capital and Stage 0 control, supporting a middling call.","value":"Shipped products and meaningful fees coexist with low capital and Stage 0 control, supporting a middling call.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:abstract:tvl","source:abstract:fees","source:abstract:l2beat"],"evidence_locator":"Capital, economics and control baseline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Repeat paying users, diversified fees and improved controls would strengthen the outlook.","value":"Repeat paying users, diversified fees and improved controls would strengthen the outlook.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:abstract:portal","source:abstract:fees","source:abstract:l2beat"],"evidence_locator":"Current product and control baseline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:abstract:section:outlook_and_watch:2","field_path":"analysis.sections.outlo